def solve():
    n, m = map(int, input().split())
    a = list(map(int, input().split()))
    segments = [tuple(map(int, input().split())) for _ in range(m)]

    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + a[i]

    max_diff = 0
    best_segments = []

    for i in range(m):
        for j in range(i, m):
            current_diff = 0
            current_segments = set()

            for k in range(n):
                min_val, max_val = float('inf'), float('-inf')
                for l in range(i, j + 1):
                    left, right = segments[l] - 1
                    if k >= left and k <= right:
                        min_val = min(min_val, prefix_sum[k + 1] - prefix_sum[left] - (k - left + 1))
                        max_val = max(max_val, prefix_sum[k + 1] - prefix_sum[left] - (k - left + 1))
                    else:
                        min_val = min(min_val, prefix_sum[k + 1] - prefix_sum[k])
                        max_val = max(max_val, prefix_sum[k + 1] - prefix_sum[k])

                current_diff += max_val - min_val
                if max_val != min_val:
                    current_segments.add(l + 1)

            if current_diff > max_diff:
                max_diff = current_diff
                best_segments = list(current_segments)

    print(max_diff)
    print(len(best_segments))
    if best_segments:
        print(*best_segments)

